      "        while (data[i] < pivot)",
      "            i \u2190 i + 1",
      "        endwhile",
      "        while (pivot < data[j])",
      "            j \u2190 j \u2212 1",
      "        endwhile",
      "        if (i \u2265 j)",
      "            \u7E70\u8FD4\u3057\u51E6\u7406\u3092\u7D42\u4E86\u3059\u308B",
      "        endif",
      "        data[i] \u3068 data[j] \u306E\u5024\u3092\u5165\u308C\u66FF\u3048\u308B",
      "        i \u2190 i + 1",
      "        j \u2190 j \u2212 1",
      "    endwhile",
