      "        return true",
      "    else",
      "        i \u2190 calcHash2(value)",
      "        if (hashArray[i] = -1)",
      "            hashArray[i] \u2190 value",
      "            return true",
      "        endif",
      "    endif",
      "    return false",
      "",
      "\u25CB \u6574\u6570\u578B: calcHash1(\u6574\u6570\u578B: value)",
